/**
 * Repository interface (TZ §8). Everything above this layer is storage-agnostic:
 * `PrismaRepository` (PostgreSQL 16) is used in production, `MemoryRepository`
 * in unit tests and for a zero-dependency dev mode. Both are checked by the
 * same contract suite (src/repo/repo.contract.ts).
 *
 * Conventions:
 *  - ids are UUID v7 generated by the app (`newId()`), so `id` order = creation order;
 *  - lists are cursor-paginated: the cursor is the opaque last sort value;
 *  - optimistic locking: `version` integers; a stale write returns 'version_mismatch';
 *  - soft delete: `deletedAt`; physical erase after 30 days via `purgeDeleted`.
 */
import type {
  Concept,
  ContentPackage,
  ContentStatus,
  Course,
  GlossaryTerm,
  I18nStatus,
  Item,
  ItemResponse,
  Lang,
  Manifest,
  Objective,
  Process,
  Subject,
  SubjectGroup,
  Topic,
  Unit,
} from '@bilig/content-model';
import type { AuthorSubrole, Role, Scope } from '@bilig/permissions';

export type Id = string;

export interface PageReq {
  cursor?: string;
  limit: number;
}
export interface PageRes<T> {
  items: T[];
  nextCursor: string | null;
}

export type WriteResult<T> = T | 'not_found' | 'version_mismatch';
export type DeleteResult = 'ok' | 'not_found' | 'version_mismatch';

// ---------------------------------------------------------------------------
// Identity & schools
// ---------------------------------------------------------------------------

export type UserKind = 'adult' | 'student';
export type UserStatus = 'active' | 'blocked' | 'invited' | 'pending';

export interface UserRec {
  id: Id;
  kind: UserKind;
  /** Lower-cased. Students never have one (TZ §6 minimisation). */
  email: string | null;
  emailVerifiedAt: Date | null;
  displayName: string;
  locale: Lang;
  status: UserStatus;
  createdAt: Date;
  updatedAt: Date;
  deletedAt: Date | null;
}

export type CredentialType = 'password' | 'pin' | 'google' | 'totp';
export interface CredentialRec {
  userId: Id;
  type: CredentialType;
  /** argon2id hash (password, pin) or the TOTP secret (base32, `pending:` prefix until verified). */
  secretHash: string;
  failedCount: number;
  lockedUntil: Date | null;
  updatedAt: Date;
}

export type Audience = 'client' | 'admin';
export interface SessionRec {
  id: Id;
  userId: Id;
  /** sha256 of the refresh token. */
  refreshHash: string;
  /** All rotations of one login share a family; reuse revokes the family. */
  family: Id;
  audience: Audience;
  device: string;
  ip: string | null;
  createdAt: Date;
  expiresAt: Date;
  revokedAt: Date | null;
  /** Set when this token was rotated (its successor id). */
  replacedById: Id | null;
}

export interface GrantRec {
  userId: Id;
  role: Role;
  scope: Scope;
  scopeId: string | null;
  subrole: AuthorSubrole | null;
}

export type AuthTokenPurpose = 'email_verify' | 'password_reset';
export interface AuthTokenRec {
  id: Id;
  userId: Id;
  purpose: AuthTokenPurpose;
  tokenHash: string;
  expiresAt: Date;
  usedAt: Date | null;
}

export interface InviteRec {
  id: Id;
  email: string;
  role: Role;
  scope: Scope;
  scopeId: string | null;
  subrole: AuthorSubrole | null;
  tokenHash: string;
  invitedBy: Id;
  createdAt: Date;
  expiresAt: Date;
  acceptedAt: Date | null;
}

export interface SchoolRec {
  id: Id;
  name: string;
  region: string;
  type: 'state' | 'private';
  language: Lang;
  status: 'active' | 'suspended';
  createdAt: Date;
}

export interface LicenseRec {
  id: Id;
  schoolId: Id;
  subjects: string[];
  grades: number[];
  seats: number;
  startsAt: Date;
  endsAt: Date;
}

export interface ClassRec {
  id: Id;
  schoolId: Id;
  name: string;
  grade: number;
  joinCode: string;
  joinCodeEnabled: boolean;
  createdBy: Id;
  createdAt: Date;
  deletedAt: Date | null;
}

export interface EnrollmentRec {
  classId: Id;
  userId: Id;
  role: 'student' | 'teacher';
  createdAt: Date;
}

export interface ConsentRec {
  studentId: Id;
  schoolId: Id;
  confirmedBy: Id;
  confirmedAt: Date;
}

// ---------------------------------------------------------------------------
// Content
// ---------------------------------------------------------------------------

export interface ContentKinds {
  group: SubjectGroup;
  subject: Subject;
  course: Course;
  unit: Unit;
  objective: Objective;
  concept: Concept;
  process: Process;
  item: Item;
  glossary: GlossaryTerm;
}
export type ContentKind = keyof ContentKinds;
export const CONTENT_KINDS: readonly ContentKind[] = [
  'group',
  'subject',
  'course',
  'unit',
  'objective',
  'concept',
  'process',
  'item',
  'glossary',
];

export interface ContentRec<T> {
  id: Id;
  key: string;
  data: T;
  /** Denormalised owning subject (RBAC scope + filters); null = shared. */
  subjectKey: string | null;
  version: number;
  createdAt: Date;
  updatedAt: Date;
  updatedBy: Id | null;
}

export interface ContentWrite<T> {
  data: T;
  subjectKey: string | null;
  /** Lower-cased text of all languages for admin search. */
  searchText: string;
}

export interface ContentFilter {
  q?: string;
  subjectKey?: string;
}

export interface ContentStore<T> {
  list(filter: ContentFilter, page: PageReq): Promise<PageRes<ContentRec<T>>>;
  get(key: string): Promise<ContentRec<T> | null>;
  getMany(keys: readonly string[]): Promise<ContentRec<T>[]>;
  /** Returns 'conflict' when the key exists. */
  create(key: string, w: ContentWrite<T>, actor: Id | null): Promise<ContentRec<T> | 'conflict'>;
  /** Pass `expectedVersion: null` to skip the optimistic check (seed/import). */
  update(key: string, w: ContentWrite<T>, expectedVersion: number | null, actor: Id | null): Promise<WriteResult<ContentRec<T>>>;
  delete(key: string, expectedVersion: number | null): Promise<DeleteResult>;
  count(): Promise<number>;
}

export interface TopicRec {
  id: Id;
  key: string;
  unitKey: string;
  subjectKey: string;
  status: ContentStatus;
  demo: boolean;
  publishedVersionId: Id | null;
  latestVersionId: Id | null;
  scheduledAt: Date | null;
  scheduledVersionId: Id | null;
  version: number;
  createdAt: Date;
  updatedAt: Date;
  deletedAt: Date | null;
}
export type TopicPatch = Partial<
  Pick<
    TopicRec,
    'unitKey' | 'subjectKey' | 'status' | 'demo' | 'publishedVersionId' | 'latestVersionId' | 'scheduledAt' | 'scheduledVersionId' | 'deletedAt'
  >
>;

export interface TopicFilter {
  q?: string;
  subjectKey?: string;
  status?: ContentStatus;
  /** Topics with a scheduled publish at or before this instant. */
  scheduledBefore?: Date;
}

export interface TopicVersionRec {
  id: Id;
  topicId: Id;
  topicKey: string;
  version: string;
  doc: Topic;
  authorId: Id;
  createdAt: Date;
  reviewState: ContentStatus;
  message: string | null;
}

export type BuildStatus = 'queued' | 'building' | 'ready' | 'failed';
export interface BuildRec {
  id: Id;
  topicId: Id;
  topicKey: string;
  topicVersionId: Id;
  version: string;
  status: BuildStatus;
  manifest: Manifest | null;
  pkg: ContentPackage | null;
  packageUrl: string | null;
  hash: string | null;
  log: string[];
  createdAt: Date;
}

export interface PublishedRec {
  topic: TopicRec;
  build: BuildRec & { manifest: Manifest; pkg: ContentPackage };
}

export interface AssetRec {
  id: Id;
  key: string;
  kind: 'glb' | 'image' | 'molfile';
  filename: string;
  contentType: string;
  license: string;
  author: string;
  source: string;
  status: 'uploaded' | 'processing' | 'ready' | 'failed';
  sizeBytes: number;
  sizeAfter: number | null;
  triangles: number | null;
  nodes: string[];
  violations: string[];
  originalUrl: string | null;
  optimizedUrl: string | null;
  thumbUrl: string | null;
  uploadId: string;
  createdBy: Id;
  createdAt: Date;
}

export interface LocaleStringRec {
  key: string;
  locale: Lang;
  value: string;
  status: I18nStatus;
  /** sha256 (hex, 16 chars) of the source (ru) text this value was translated from. */
  sourceHash: string;
  updatedAt: Date;
}
export interface StringFilter {
  locale?: Lang;
  status?: I18nStatus;
  keyPrefix?: string;
}

export interface ReviewCommentRec {
  id: Id;
  targetType: 'topic' | 'concept' | 'process' | 'item';
  targetId: Id;
  path: string;
  body: string;
  authorId: Id;
  createdAt: Date;
  resolvedAt: Date | null;
}

// ---------------------------------------------------------------------------
// Learning, decks, tutor, events, audit
// ---------------------------------------------------------------------------

export interface ProgressRec {
  userId: Id;
  topicKey: string;
  visitedConcepts: string[];
  completedActivities: string[];
  updatedAt: Date;
}

export interface AssignmentRec {
  id: Id;
  classId: Id;
  topicKey: string;
  activities: string[];
  dueAt: Date | null;
  createdBy: Id;
  createdAt: Date;
}

export interface AttemptRec {
  id: Id;
  userId: Id;
  clientId: Id;
  assignmentId: Id | null;
  topicKey: string;
  topicVersion: string;
  topicVersionId: Id;
  seed: string;
  itemKeys: string[];
  startedAt: Date;
  finishedAt: Date | null;
  score: number | null;
  /** 'online' (answers checked one by one) or 'sync' (offline batch). */
  source: 'online' | 'sync';
}

export interface AnswerRec {
  id: Id;
  attemptId: Id;
  itemKey: string;
  response: ItemResponse;
  correct: boolean;
  score: number;
  timeMs: number;
  answeredAt: Date;
}

export interface AttemptFilter {
  userId?: Id;
  userIds?: Id[];
  assignmentId?: Id;
  from?: Date;
  to?: Date;
}

export interface PresentationRec {
  id: Id;
  ownerId: Id;
  topicKey: string;
  title: string;
  lang: Lang;
  slides: unknown[];
  version: number;
  createdAt: Date;
  updatedAt: Date;
}

export interface SnapshotRec {
  id: Id;
  ownerId: Id;
  topicKey: string;
  topicVersion: string;
  imageKey: string;
  imageUrl: string;
  sceneState: unknown;
  createdAt: Date;
}

export interface TutorThreadRec {
  id: Id;
  userId: Id | null;
  topicKey: string;
  createdAt: Date;
}
export interface TutorMessageRec {
  id: Id;
  threadId: Id;
  role: 'user' | 'assistant';
  /** Masked text (names/phones removed) — what was actually sent to the provider. */
  text: string;
  citations: string[];
  inputTokens: number;
  outputTokens: number;
  /** Refused / off-topic / suspected injection / provider failure. */
  flagged: boolean;
  topicKey: string;
  schoolId: Id | null;
  createdAt: Date;
}

export interface LearningEventRec {
  id: Id;
  /** HMAC pseudonym of the user id, or `guest`. Never the raw id (TZ §8). */
  actor: string;
  verb: string;
  objectType: string;
  objectKey: string;
  topicKey: string | null;
  result: unknown;
  context: unknown;
  ts: Date;
  receivedAt: Date;
}

export interface AuditRec {
  id: Id;
  actorId: Id | null;
  action: string;
  targetType: string;
  targetId: string;
  diff: unknown;
  ip: string | null;
  ts: Date;
}
export interface AuditFilter {
  actorId?: Id;
  action?: string;
  targetType?: string;
}

export interface IdempotencyRec {
  userId: Id;
  key: string;
  requestHash: string;
  response: unknown;
  createdAt: Date;
}

export interface SettingRec {
  key: string;
  value: unknown;
  version: number;
  updatedAt: Date;
}

// ---------------------------------------------------------------------------
// The repository
// ---------------------------------------------------------------------------

export interface UserFilter {
  q?: string;
  ids?: Id[];
  status?: UserStatus;
}

export interface Repository {
  readonly kind: 'memory' | 'prisma';
  ping(): Promise<boolean>;
  close(): Promise<void>;

  // identity
  createUser(u: Omit<UserRec, 'createdAt' | 'updatedAt' | 'deletedAt'>): Promise<UserRec | 'conflict'>;
  getUser(id: Id): Promise<UserRec | null>;
  getUserByEmail(email: string): Promise<UserRec | null>;
  updateUser(id: Id, patch: Partial<Pick<UserRec, 'displayName' | 'locale' | 'status' | 'emailVerifiedAt' | 'deletedAt'>>): Promise<UserRec | null>;
  listUsers(filter: UserFilter, page: PageReq): Promise<PageRes<UserRec>>;
  getUsers(ids: readonly Id[]): Promise<UserRec[]>;

  getCredential(userId: Id, type: CredentialType): Promise<CredentialRec | null>;
  setCredential(userId: Id, type: CredentialType, secretHash: string): Promise<void>;
  updateCredential(userId: Id, type: CredentialType, patch: Partial<Pick<CredentialRec, 'failedCount' | 'lockedUntil'>>): Promise<void>;
  deleteCredential(userId: Id, type: CredentialType): Promise<void>;

  listGrants(userId: Id): Promise<GrantRec[]>;
  listGrantsByScope(scope: Scope, scopeId: string): Promise<GrantRec[]>;
  setGrants(userId: Id, grants: Omit<GrantRec, 'userId'>[]): Promise<void>;
  addGrant(grant: GrantRec): Promise<void>;

  createSession(s: SessionRec): Promise<void>;
  getSession(id: Id): Promise<SessionRec | null>;
  getSessionByRefreshHash(hash: string): Promise<SessionRec | null>;
  /**
   * Atomic rotation: marks `oldId` revoked+replaced and inserts `next` only if
   * `oldId` was still active. Returns false when it was already rotated/revoked
   * (a concurrent refresh or a replay).
   */
  rotateSession(oldId: Id, next: SessionRec, at: Date): Promise<boolean>;
  revokeSession(id: Id, at: Date): Promise<void>;
  revokeFamily(family: Id, at: Date): Promise<number>;
  revokeUserSessions(userId: Id, at: Date): Promise<number>;
  listActiveSessions(userId: Id, now: Date): Promise<SessionRec[]>;

  createAuthToken(t: AuthTokenRec): Promise<void>;
  /** Marks the token used and returns it, or null if unknown/expired/used. */
  consumeAuthToken(tokenHash: string, purpose: AuthTokenPurpose, now: Date): Promise<AuthTokenRec | null>;

  createInvite(i: InviteRec): Promise<void>;
  getInviteByHash(tokenHash: string): Promise<InviteRec | null>;
  markInviteAccepted(id: Id, at: Date): Promise<boolean>;
  listInvites(filter: { scope?: Scope; scopeIds?: string[] }, page: PageReq): Promise<PageRes<InviteRec>>;

  createSchool(s: SchoolRec): Promise<void>;
  getSchool(id: Id): Promise<SchoolRec | null>;
  updateSchool(id: Id, patch: Partial<Omit<SchoolRec, 'id' | 'createdAt'>>): Promise<SchoolRec | null>;
  listSchools(filter: { ids?: Id[] }, page: PageReq): Promise<PageRes<SchoolRec>>;

  createLicense(l: LicenseRec): Promise<LicenseRec | 'conflict'>;
  getLicense(id: Id): Promise<LicenseRec | null>;
  updateLicense(id: Id, patch: Partial<Omit<LicenseRec, 'id' | 'schoolId'>>): Promise<LicenseRec | null>;
  deleteLicense(id: Id): Promise<boolean>;
  listLicenses(filter: { schoolIds?: Id[] }, page: PageReq): Promise<PageRes<LicenseRec>>;

  createClass(c: ClassRec): Promise<ClassRec | 'conflict'>;
  getClass(id: Id): Promise<ClassRec | null>;
  getClassByJoinCode(code: string): Promise<ClassRec | null>;
  updateClass(id: Id, patch: Partial<Pick<ClassRec, 'name' | 'grade' | 'joinCode' | 'joinCodeEnabled' | 'deletedAt'>>): Promise<ClassRec | null | 'conflict'>;
  listClasses(filter: { ids?: Id[]; schoolIds?: Id[] }, page: PageReq): Promise<PageRes<ClassRec>>;

  addEnrollment(e: Omit<EnrollmentRec, 'createdAt'>): Promise<void>;
  removeEnrollment(classId: Id, userId: Id): Promise<void>;
  listEnrollments(filter: { classId?: Id; classIds?: Id[]; userId?: Id; role?: 'student' | 'teacher' }): Promise<EnrollmentRec[]>;

  setConsent(c: ConsentRec | { studentId: Id; remove: true }): Promise<void>;
  listConsents(studentIds: readonly Id[]): Promise<ConsentRec[]>;

  // content
  content<K extends ContentKind>(kind: K): ContentStore<ContentKinds[K]>;

  createTopic(t: Omit<TopicRec, 'createdAt' | 'updatedAt' | 'deletedAt' | 'version'>): Promise<TopicRec | 'conflict'>;
  getTopic(id: Id): Promise<TopicRec | null>;
  getTopicByKey(key: string): Promise<TopicRec | null>;
  updateTopic(id: Id, patch: TopicPatch, expectedVersion: number | null): Promise<WriteResult<TopicRec>>;
  listTopics(filter: TopicFilter, page: PageReq): Promise<PageRes<TopicRec>>;

  createTopicVersion(v: TopicVersionRec): Promise<TopicVersionRec | 'conflict'>;
  getTopicVersion(id: Id): Promise<TopicVersionRec | null>;
  getTopicVersionBySemver(topicId: Id, version: string): Promise<TopicVersionRec | null>;
  listTopicVersions(topicId: Id): Promise<TopicVersionRec[]>;
  updateTopicVersion(id: Id, patch: Partial<Pick<TopicVersionRec, 'reviewState' | 'doc'>>): Promise<TopicVersionRec | null>;
  /** Topic versions (any state) whose doc references the concept key. */
  topicsUsingConcept(conceptKey: string): Promise<string[]>;

  createBuild(b: BuildRec): Promise<void>;
  updateBuild(id: Id, patch: Partial<Omit<BuildRec, 'id'>>): Promise<BuildRec | null>;
  getBuild(id: Id): Promise<BuildRec | null>;
  /** Latest `ready` build for a topic version. */
  readyBuildForVersion(topicVersionId: Id): Promise<BuildRec | null>;
  listBuilds(filter: { topicKey?: string }, page: PageReq): Promise<PageRes<BuildRec>>;
  /** Published topics with their ready build (catalog source). */
  listPublished(): Promise<PublishedRec[]>;

  createAsset(a: AssetRec): Promise<void>;
  getAsset(id: Id): Promise<AssetRec | null>;
  updateAsset(id: Id, patch: Partial<Omit<AssetRec, 'id'>>): Promise<AssetRec | null>;
  listAssets(page: PageReq): Promise<PageRes<AssetRec>>;

  listStrings(filter: StringFilter, page: PageReq): Promise<PageRes<LocaleStringRec>>;
  getStrings(keys: readonly string[]): Promise<LocaleStringRec[]>;
  upsertStrings(rows: readonly LocaleStringRec[]): Promise<void>;

  createReviewComment(c: ReviewCommentRec): Promise<void>;

  // learning
  getProgress(userId: Id, topicKey: string): Promise<ProgressRec | null>;
  putProgress(p: ProgressRec): Promise<void>;

  createAssignment(a: AssignmentRec): Promise<void>;
  getAssignment(id: Id): Promise<AssignmentRec | null>;
  listAssignments(filter: { classIds: Id[] }, page: PageReq): Promise<PageRes<AssignmentRec>>;

  /** Returns 'conflict' when (userId, clientId) already exists. */
  createAttempt(a: AttemptRec): Promise<AttemptRec | 'conflict'>;
  getAttempt(id: Id): Promise<AttemptRec | null>;
  getAttemptByClientId(userId: Id, clientId: Id): Promise<AttemptRec | null>;
  updateAttempt(id: Id, patch: Partial<Pick<AttemptRec, 'finishedAt' | 'score'>>): Promise<AttemptRec | null>;
  listAttempts(filter: AttemptFilter): Promise<AttemptRec[]>;

  /** Returns 'conflict' when the item was already answered in that attempt. */
  createAnswer(a: AnswerRec): Promise<AnswerRec | 'conflict'>;
  listAnswers(filter: { attemptIds?: Id[]; itemKey?: string }): Promise<AnswerRec[]>;

  /** Insert events; ids already stored are counted as duplicates. */
  insertEvents(events: readonly LearningEventRec[]): Promise<{ accepted: number; duplicates: number }>;
  listEvents(filter: { from?: Date; to?: Date }): Promise<LearningEventRec[]>;

  getIdempotency(userId: Id, key: string): Promise<IdempotencyRec | null>;
  /** Returns false when the key already exists (lost race). */
  putIdempotency(r: IdempotencyRec): Promise<boolean>;

  // decks
  createPresentation(p: PresentationRec): Promise<void>;
  getPresentation(id: Id): Promise<PresentationRec | null>;
  updatePresentation(id: Id, patch: Partial<Pick<PresentationRec, 'title' | 'slides'>>, expectedVersion: number): Promise<WriteResult<PresentationRec>>;
  deletePresentation(id: Id): Promise<boolean>;
  listPresentations(ownerId: Id, page: PageReq): Promise<PageRes<PresentationRec>>;
  createSnapshot(s: SnapshotRec): Promise<void>;
  getSnapshot(id: Id): Promise<SnapshotRec | null>;
  getSnapshots(ids: readonly Id[]): Promise<SnapshotRec[]>;

  // tutor
  createThread(t: TutorThreadRec): Promise<void>;
  getThread(id: Id): Promise<TutorThreadRec | null>;
  addTutorMessage(m: TutorMessageRec): Promise<void>;
  listTutorMessages(filter: { threadId?: Id; from?: Date; to?: Date; limit?: number }): Promise<TutorMessageRec[]>;

  // audit & settings
  appendAudit(a: AuditRec): Promise<void>;
  listAudit(filter: AuditFilter, page: PageReq): Promise<PageRes<AuditRec>>;
  getSetting(key: string): Promise<SettingRec | null>;
  /** expectedVersion null = upsert without check (defaults/seed). */
  putSetting(key: string, value: unknown, expectedVersion: number | null): Promise<WriteResult<SettingRec>>;

  /** Physically erase soft-deleted users/classes older than `before` (TZ §6: 30 days). */
  purgeDeleted(before: Date): Promise<{ users: number; classes: number }>;
}
